create table public.cliente_ruleta_catalogo("id" text,"nivel" smallint,"reward_type" text,"reward_value" integer,"weight" integer,"special" boolean default false,"active" boolean default true,"version" integer default 1);
create table public.tc_client_rituals("id" uuid default gen_random_uuid(),"cliente_id" uuid,"ritual_type_id" uuid,"mode" text default 'automatic'::text,"status" text default 'active'::text,"starts_at" timestamp with time zone default now(),"ends_at" timestamp with time zone,"duration_days" integer default 7,"progress_override" numeric(5,2) default 0,"progress_adjustment" numeric(6,2) default 0,"phase_override_id" uuid,"message_override" text,"today_message_override" text,"advice_override" text,"video_override_url" text,"poster_override_url" text,"paused_at" timestamp with time zone,"paused_total_seconds" bigint default 0,"completed_at" timestamp with time zone,"created_by" uuid,"updated_by" uuid,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now());
create table public.tc_client_roulette_audit("id" uuid default gen_random_uuid(),"campaign_id" uuid,"reward_id" uuid,"spin_id" uuid,"cliente_id" uuid,"actor_user_id" uuid,"action" text,"snapshot" jsonb default '{}'::jsonb,"created_at" timestamp with time zone default now());
